from pathlib import Path

import pytest

from agent_harness.env import command

DECLARED = """
[keys.DATABASE_URL]
block = "Database"
summary = "The Postgres connection string"
required = true
secret = true

[keys.DATABASE_POOL]
block = "Database"
default = "5"
environments = ["production"]

[keys.LOG_LEVEL]
block = "Logging"
summary = "The lowest level that prints"
default = "info"

[environments.dev]
LOG_LEVEL = "debug"
"""

MASTER = """# Generated by `ah env template --master` from the env declarations. Do not edit it.
#
# Every other env file follows its blocks and key order.

# Database
# The Postgres connection string
DATABASE_URL=
DATABASE_POOL=5

# Logging
# The lowest level that prints
LOG_LEVEL=info
"""


@pytest.fixture
def repo(tmp_path: Path) -> Path:
    root = tmp_path / "repo"
    (root / ".git").mkdir(parents=True)
    (root / "env.toml").write_text(DECLARED, encoding="utf-8")
    return root


def run(repo: Path, *argv: str) -> tuple[int, list[str]]:
    out: list[str] = []
    code = command.main(
        ["--root", str(repo), "--declarations", "env.toml", *argv], out=out.append, err=out.append
    )
    return code, out


def read(repo: Path, name: str) -> str:
    return (repo / name).read_text(encoding="utf-8")


def test_writes_the_master_and_a_template_per_environment(repo: Path) -> None:
    code, out = run(repo, "template", "--master")

    assert (code, out) == (
        0,
        [
            "wrote .env.example: 3 keys",
            "wrote .env.dev.example: 2 keys",
            "wrote .env.production.example: 3 keys",
        ],
    )
    assert read(repo, ".env.example") == MASTER
    assert (
        read(repo, ".env.dev.example")
        == "# Database\nDATABASE_URL=\n\n# Logging\nLOG_LEVEL=debug\n"
    )
    assert read(repo, ".env.production.example") == (
        "# Database\nDATABASE_URL=\nDATABASE_POOL=\n\n# Logging\nLOG_LEVEL=\n"
    )
    assert run(repo, "layout") == (0, ["3 env files follow the layout"])


def test_fails_the_check_on_a_stale_or_missing_template_and_writes_nothing(repo: Path) -> None:
    run(repo, "template", "--master")
    (repo / ".env.example").write_text(MASTER.replace("info", "warn"), encoding="utf-8")
    (repo / ".env.dev.example").unlink()

    code, out = run(repo, "template", "--master", "--check")

    assert (code, out) == (
        1,
        [
            "stale: .env.example",
            "missing: .env.dev.example",
            "2 templates differ from the declarations. Run ah env template --master.",
        ],
    )
    assert not (repo / ".env.dev.example").exists()


def test_passes_the_check_when_every_template_is_current(repo: Path) -> None:
    run(repo, "template", "--master")

    assert run(repo, "template", "--master", "--check") == (
        0,
        ["3 templates match the declarations"],
    )


def test_refuses_the_master_form_without_declarations(tmp_path: Path) -> None:
    (tmp_path / ".git").mkdir()
    out: list[str] = []

    code = command.main(["--root", str(tmp_path), "template", "--master"], err=out.append)

    assert (code, out) == (
        1,
        ["ah env: template --master writes from the declarations, and none are configured"],
    )
